import { DOMParser, XMLSerializer } from "@xmldom/xmldom";
import { describe, expect, it } from "vitest";
import { compileYangXPath, qualifyYangXPathNodeTests } from "../src/internal.js";
import { parseXml, serializeNode } from "./dom.js";

const NAMESPACE = "urn:example:if";
const PREFIX = "if";
/** Never generated by the corpus; reserved for compileYangXPath's own auto-prefix. */
const AUTO_PREFIX = "__yang_ns";

/** Deterministic PRNG (mulberry32): every fuzz case is reproducible from the seed. */
function mulberry32(seed: number): () => number {
  return () => {
    let t = (seed += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function pick<T>(rng: () => number, items: readonly T[]): T {
  return items[Math.floor(rng() * items.length) % items.length]!;
}

const document = parseXml(`<interfaces xmlns="${NAMESPACE}" xmlns:old="urn:example:old">
  <interface><name>eth0</name><speed>100</speed><mtu>1500</mtu><enabled>true</enabled></interface>
  <interface><name>eth1</name><speed>10</speed><mtu>900</mtu><enabled>false</enabled></interface>
  <interface><name>wifi0</name><speed>10</speed><mtu>1500</mtu><enabled>true</enabled></interface>
  <foreign xmlns="urn:example:other"><interface><name>not-ours</name></interface></foreign>
</interfaces>`);
const contextNode = document.documentElement;

interface Step {
  /** Bare spelling as YANG instances are written in the current module. */
  bare: string;
  /** Explicitly prefixed spelling of the same node test. */
  prefixed: string;
}

const STEPS: Step[] = [
  { bare: "interface", prefixed: "if:interface" },
  { bare: "name", prefixed: "if:name" },
  { bare: "speed", prefixed: "if:speed" },
  { bare: "mtu", prefixed: "if:mtu" },
  { bare: "enabled", prefixed: "if:enabled" },
  { bare: "@mtu", prefixed: "@if:mtu" },
];

/** Bracketed predicates only — each is valid directly after any step. */
const PREDICATE_PAIRS: Array<(prefixed: boolean) => string> = [
  prefixed => `[${prefixed ? "if:name" : "name"}='eth0']`,
  prefixed => `[${prefixed ? "if:enabled" : "enabled"}='true']`,
  prefixed => `[position() < 3]`,
  prefixed => `[contains(${prefixed ? "if:name" : "name"}, 'and-or-div')]`,
  prefixed => `[string(${prefixed ? "if:speed" : "speed"})='10']`,
];

/** Abstract location path: rendered in both spellings, so '/' only joins steps. */
interface AbstractPath {
  step: Step;
  child?: AbstractPath;
  predicate?: (prefixed: boolean) => string;
}

function generateAbstractPath(rng: () => number, remainingDepth: number): AbstractPath {
  const path: AbstractPath = { step: pick(rng, STEPS) };
  if (rng() < 0.6 && remainingDepth > 0) path.child = generateAbstractPath(rng, remainingDepth - 1);
  if (rng() < 0.55) path.predicate = pick(rng, PREDICATE_PAIRS);
  return path;
}

function renderPath(path: AbstractPath, prefixed: boolean, parts: string[] = []): string {
  parts.push(prefixed ? path.step.prefixed : path.step.bare);
  if (path.predicate) parts.push(path.predicate(prefixed));
  if (path.child) parts.push("/");
  if (path.child) return renderPath(path.child, prefixed, parts);
  return parts.join("");
}

/** Generate an XPath expression plus the equivalent explicitly prefixed spelling. */
function generateExpressionPair(rng: () => number): { bare: string; prefixed: string } {
  // Same abstract path, same wrapper: the pair differs only in spelling.
  const abstract = generateAbstractPath(rng, 2);
  const wrapCase = Math.floor(rng() * 5);
  return { bare: wrapAsExpression(wrapCase, renderPath(abstract, false)), prefixed: wrapAsExpression(wrapCase, renderPath(abstract, true)) };
}

function wrapAsExpression(caseIndex: number, path: string): string {
  switch (caseIndex % 5) {
    case 0: return `count(${path})`;
    case 1: return `string(${path})`;
    case 2: return `${path} = 'eth0'`;
    case 3: return `not(${path})`;
    default: return path;
  }
}

/** Node-set identity independent of document order conventions: serialize each node. */
function stamp(node: Node): string {
  if (node.nodeType === 2) return `@${node.nodeName}=${node.nodeValue}`;
  return serializeNode(node);
}

interface Outcome {
  compileError?: string;
  select?: string[] | string;
  boolean?: boolean | string;
  number?: string;
  string?: string;
}

function outcomeOf(expression: string, importedNamespaces: Readonly<Record<string, string>> = {}): Outcome {
  let compiled;
  try {
    compiled = compileYangXPath(expression, NAMESPACE, importedNamespaces);
  } catch (error) {
    return { compileError: error instanceof Error ? error.message : String(error) };
  }
  const outcome: Outcome = {};
  // Sampled expressions may legitimately be scalar-typed; select() then
  // throws a conversion message. Each accessor is compared individually so a
  // divergent spelling shows up in the exact accessor where it diverges.
  try { outcome.select = compiled.select({ node: contextNode }).map(stamp); }
  catch (error) { outcome.select = error instanceof Error ? error.message : String(error); }
  try { outcome.boolean = compiled.evaluateBoolean({ node: contextNode }); }
  catch (error) { outcome.boolean = error instanceof Error ? error.message : String(error); }
  try { outcome.number = String(compiled.evaluateNumber({ node: contextNode })); }
  catch (error) { outcome.number = error instanceof Error ? error.message : String(error); }
  try { outcome.string = compiled.evaluateString({ node: contextNode }); }
  catch (error) { outcome.string = error instanceof Error ? error.message : String(error); }
  return outcome;
}

describe("XPath rewrite differential fuzz corpus (qualifyYangXPathNodeTests)", () => {
  it("rewrites a seeded corpus without changing the meaning of the expression", () => {
    const rng = mulberry32(0xc0ffee);
    const generated: [string, string][] = [];
    for (let index = 0; index < 300; index++) {
      const pair = generateExpressionPair(rng);
      generated.push([pair.bare, pair.prefixed]);
    }
    for (const [bare, prefixed] of generated) {
      // 1. The rewrite is a pure prefix insertion: undoing the auto prefix
      //    restores the source byte for byte (no quoted literal or operator
      //    was rewritten).
      const qualified = qualifyYangXPathNodeTests(bare, AUTO_PREFIX);
      expect(qualified.split(`${AUTO_PREFIX}:`).join("")).toBe(bare);
      // 2. The auto-qualified bare form and the explicitly prefixed form are
      //    the same expression in two spellings — both must compile (the
      //    corpus grammar is valid) and agree on every accessor.
      const bareOutcome = outcomeOf(bare);
      expect(bareOutcome.compileError).toBeUndefined();
      const prefixedOutcome = outcomeOf(prefixed, { [PREFIX]: NAMESPACE });
      expect(prefixedOutcome.compileError).toBeUndefined();
      expect(bareOutcome).toEqual(prefixedOutcome);
    }
  });

  it("differs a curated corpus of tricky tokens from their nearest wrong rewrite", () => {
    // Each entry: expression, plus a string that a naive qualifier would
    // produce and that MUST NOT appear in the qualified source.
    const cases: Array<[string, string]> = [
      ["string(name)", "string(__yang_ns:string)"],
      ["child::name", "child::__yang_ns:child"],
      ["count(interface)", "__yang_ns:count"],
      ["@mtu", "__yang_ns:@"],
      ["speed div 2 = 50", "__yang_ns:div"],
      ["speed mod 3 = 1", "__yang_ns:mod"],
      ["enabled = 'true' and position() = 1", "__yang_ns:and"],
      ["$var", "__yang_ns:$"],
      ["if:name", "if:if:name"],
      ["concat('::and ', name)", "__yang_ns:'::and '"],
      ["derived-from(../type,'t:ethernet')", "__yang_ns:derived"],
      ["current()/name", "__yang_ns:current"],
    ];
    for (const [expression, forbidden] of cases) {
      const qualified = qualifyYangXPathNodeTests(expression, AUTO_PREFIX);
      expect(qualified).not.toContain(forbidden);
      expect(compileYangXPath(expression, NAMESPACE, { if: NAMESPACE }).qualifiedSource)
        .toBe(qualifyYangXPathNodeTests(expression, AUTO_PREFIX));
    }
  });

  it("keeps literals containing the reserved auto-prefix usable by escaping the prefix", () => {
    // A quoted literal spelling the auto prefix must not collide with it:
    // unusedPrefix has to move aside, and both spellings keep evaluating.
    const expression = "name = 'oops __yang_ns:name'";
    const compiled = compileYangXPath(expression, NAMESPACE);
    expect(compiled.qualifiedSource).not.toContain(`${AUTO_PREFIX}:name =`);
    expect(compiled.evaluateBoolean({ node: contextNode })).toBe(false);
    const prefixed = compileYangXPath("if:name = 'oops __yang_ns:name'", NAMESPACE, { if: NAMESPACE });
    expect(prefixed.evaluateBoolean({ node: contextNode })).toBe(false);
    expect(serializeNode(document)).toContain("eth1");
  });
});
